          "२. तत्पुरुष: विग्रह करताना विभक्ती प्रत्यय लागतो. उदा. देवपूजा = देवाची पूजा (षष्ठी तत्पुरुष). उपप्रकार: कर्मधारय (विशेषण+नाम: महादेव, रक्तचंदन), द्विगु (संख्या+समूह: सप्ताह).",
